function tick(){const dt=Math.min(clock.getDelta(),.05);elapsed+=dt;if(running&&!paused&&!dead)step(dt);animate(dt);renderer.render(scene,camera);}
function step(dt){attackTimer=Math.max(0,attackTimer-dt);attackAnim=Math.max(0,attackAnim-dt);invulnerable=Math.max(0,invulnerable-dt);mp=Math.min(maxMp,mp+dt*(2.2+(level-1)*.22));for(let i=0;i<3;i++){skillTimers[i]=Math.max(0,skillTimers[i]-dt);const el=document.querySelector('#skill'+(i+1));el.classList.toggle('cooling',skillTimers[i]>.05);el.dataset.cool=skillTimers[i]>.05?Math.ceil(skillTimers[i]):'';}
let dx=0,dz=0;if(keys.KeyW||keys.ArrowUp)dz-=1;if(keys.KeyS||keys.ArrowDown)dz+=1;if(keys.KeyA||keys.ArrowLeft)dx-=1;if(keys.KeyD||keys.ArrowRight)dx+=1;dx+=joystick.x;dz+=joystick.y;const len=Math.hypot(dx,dz);if(len>1){dx/=len;dz/=len;}if(len>.05){player.position.x+=dx*4.25*dt;player.position.z+=dz*4.25*dt;player.rotation.y=Math.atan2(dx,dz);}
player.position.x=THREE.MathUtils.clamp(player.position.x,-7.2,7.2);player.position.z=THREE.MathUtils.clamp(player.position.z,-7.2,7.2);if(attackAnim>0)player.rotation.y+=Math.sin((attackAnim/.5)*Math.PI)*.035;
spawnTimer-=dt;if(spawnTimer<=0){const count=Math.min(3+wave,12);if(enemies.filter(e=>e.hp>0).length<count)spawnEnemy();spawnTimer=Math.max(.65,2.1-wave*.12);}
for(const e of enemies){if(e.hp<=0)continue;e.attack-=dt;e.hit=Math.max(0,e.hit-dt);e.slow=Math.max(0,(e.slow||0)-dt);e.walk+=dt*6;const dir=player.position.clone().sub(e.group.position);dir.y=0;const dist=dir.length();if(dist>1.12){dir.normalize();const sp=e.speed*(e.slow>0?.48:1);e.group.position.addScaledVector(dir,sp*dt);e.group.rotation.y=Math.atan2(dir.x,dir.z);e.group.position.y=Math.abs(Math.sin(e.walk))*0.025;}else if(e.attack<=0){e.attack=e.type==='brute'?1.5:1.15;if(invulnerable<=0){hp-=e.damage;invulnerable=.65;document.querySelector('#damage').style.opacity='.16';setTimeout(()=>document.querySelector('#damage').style.opacity='0',110);updateHud();if(hp<=0){hp=0;endGame(false);}}}}
for(const t of torches){let f=1+Math.sin(elapsed*8+t.offset)*.12+Math.sin(elapsed*17+t.offset)*.05;t.flame.scale.y=1.5*f;t.light.intensity=3.5*f;}
for(let i=effects.length-1;i>=0;i--){const fx=effects[i];fx.age+=dt;if(fx.kind==='bolt'&&fx.userData.target?.hp>0){const target=fx.userData.target.group.position.clone().add(new THREE.Vector3(0,1,0)),dir=target.clone().sub(fx.group.position);if(dir.length()<.35){hitEnemy(fx.userData.target,fx.userData.damage);scene.remove(fx.group);effects.splice(i,1);continue;}fx.group.position.addScaledVector(dir.normalize(),12*dt);}else if(fx.kind==='orb'){fx.group.position.y=.35+Math.sin(elapsed*4)*.1;if(fx.group.position.distanceTo(player.position)<.8){hp=Math.min(maxHp,hp+12);mp=Math.min(maxMp,mp+8);updateHud();scene.remove(fx.group);effects.splice(i,1);continue;}}else{fx.obj.scale.setScalar(1+fx.age*4);if(fx.obj.material.opacity!==undefined)fx.obj.material.opacity=Math.max(0,.8-fx.age*1.6);}if(fx.age>(fx.kind==='bolt'?2:fx.kind==='orb'?15:.42)){scene.remove(fx.group);effects.splice(i,1);}}
// camera follows the wanderer with a soft, fixed isometric offset
const desired=new THREE.Vector3(player.position.x,15.5,player.position.z+16);camera.position.lerp(desired,1-Math.exp(-dt*2.7));camera.lookAt(player.position.x,0,player.position.z);}
function animate(dt){if(!player)return;player.children.forEach(c=>{if(c.geometry.type==='BoxGeometry'&&c.position.x>.3&&c.position.y>.8){c.rotation.z=attackAnim>0?-Math.sin(attackAnim*9)*1.25:-.42;}});for(const e of enemies)if(e.hp>0&&e.hit>0){e.group.children.forEach(c=>{if(c.material?.emissive){c.material.emissive.setHex(0x5d1712);c.material.emissiveIntensity=e.hit*2;}});}else if(e.hp>0)e.group.children.forEach(c=>{if(c.material?.emissive)c.material.emissiveIntensity=0;});}
function endGame(victory){dead=true;running=false;document.querySelector('#endTitle').textContent=victory?'HOLLOW CLEARED':'FALLEN';document.querySelector('#endText').textContent=victory?'The chapel is quiet. For now, the dead are at rest.':'The Hollow claims another soul. But the dark is never the end.';document.querySelector('#gameover').classList.remove('hidden');}
